      en: { q: "What do you call money with which the state supports businesses for a specific purpose (e.g. funding for solar panels)?", a: ["subsidy", "subsidies", "grant", "grants", "state aid"], e: "Subsidies are earmarked payments from the state to businesses, e.g. for research or solar power. Taxes flow the other way – from businesses to the state." },
      hu: { q: "Hogyan nevezzük azt a pénzt, amellyel az állam egy meghatározott célra támogatja a vállalkozásokat (pl. napelemes támogatás)?", a: ["támogatás", "támogatások", "szubvenció", "szubvenciók", "állami támogatás"], e: "A támogatások (szubvenciók) az állam célhoz kötött kifizetései a vállalkozásoknak, például kutatásra vagy napenergiára. Az adók fordított irányba áramlanak – a vállalkozástól az államhoz." },
